mapper.select:
SELECT COUNT(*) FROM ( SELECT "LEVEL" , CASE WHEN LOWER(MSG) LIKE '%login%' OR MSG LIKE '%인증%' OR MSG LIKE '%로그인%' THEN 'auth' WHEN LOWER(MSG) LIKE '%pay%' OR MSG LIKE '%결제%' THEN 'payment' WHEN LOWER(MSG) LIKE '%book%' OR MSG LIKE '%예약%' THEN 'booking' WHEN LOWER(MSG) LIKE '%product%' OR LOWER(MSG) LIKE '%accommodation%' OR LOWER(MSG) LIKE '%flight%' OR LOWER(MSG) LIKE '%tour%' THEN 'product' WHEN LOWER(MSG) LIKE '%security%' OR MSG LIKE '%보안%' OR MSG LIKE '%접근%' THEN 'security' ELSE 'system' END AS CATEGORY FROM SYSTEM_LOG WHERE REG_DT BETWEEN TO_DATE(#{startDate} || ' 00:00:00', 'YYYY-MM-DD HH24:MI:SS') AND TO_DATE(#{endDate} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS')
AND (MSG LIKE '%' || #{searchWord} || '%' OR SOURCE LIKE '%' || #{searchWord} || '%')
)
AND CATEGORY = #{searchType}
AND "LEVEL" = #{levelFilter}

SELECT SYSTEM_LOG_NO, "LEVEL", SOURCE, MSG, IP, REG_DT, SYSTEM_LOG_MEM FROM ( SELECT ROWNUM RNUM, TT.* FROM ( SELECT SYSTEM_LOG_NO, "LEVEL", SOURCE, MSG, IP, REG_DT, SYSTEM_LOG_MEM FROM ( SELECT SYSTEM_LOG_NO, "LEVEL", SOURCE, MSG, IP, REG_DT, SYSTEM_LOG_MEM , CASE WHEN LOWER(MSG) LIKE '%login%' OR MSG LIKE '%인증%' OR MSG LIKE '%로그인%' THEN 'auth' WHEN LOWER(MSG) LIKE '%pay%' OR MSG LIKE '%결제%' THEN 'payment' WHEN LOWER(MSG) LIKE '%book%' OR MSG LIKE '%예약%' THEN 'booking' WHEN LOWER(MSG) LIKE '%product%' OR LOWER(MSG) LIKE '%accommodation%' OR LOWER(MSG) LIKE '%flight%' OR LOWER(MSG) LIKE '%tour%' THEN 'product' WHEN LOWER(MSG) LIKE '%security%' OR MSG LIKE '%보안%' OR MSG LIKE '%접근%' THEN 'security' ELSE 'system' END AS CATEGORY FROM SYSTEM_LOG WHERE REG_DT BETWEEN TO_DATE(#{startDate} || ' 00:00:00', 'YYYY-MM-DD HH24:MI:SS') AND TO_DATE(#{endDate} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS')
AND (MSG LIKE '%' || #{searchWord} || '%' OR SOURCE LIKE '%' || #{searchWord} || '%')
)
AND CATEGORY = #{searchType}
AND "LEVEL" = #{levelFilter}
ORDER BY REG_DT DESC, SYSTEM_LOG_NO DESC ) TT
WHERE ROWNUM <= #{endRow}
)
WHERE RNUM >= #{startRow}
